// scannerPluginKey is the PluginSet key Serve assigns to the first plugin. The
// client dispenses the same key (this is the keying contract Serve provides
// for cross-process agreement).
const scannerPluginKey = "0"

const (
	testCookieKey   = "MELLIFERA_TEST_COOKIE"
	testCookieValue = "test-secret"
)

// fakeScanner is the in-process second implementation of Scanner (R8): it
// emits a fixed set of DiscoveredFiles on Scan and returns a fixed
// IdentifyResult. Together with the subprocess client wrapper built by
// ScannerPlugin.GRPCClient, it is the justification for the Scanner interface.
type fakeScanner struct {
	files  []*scannerv1.DiscoveredFile
	result *scannerv1.IdentifyResult
}

func (f fakeScanner) Scan(ctx context.Context, _ *scannerv1.ScanRequest) (<-chan *scannerv1.DiscoveredFile, error) {
	ch := make(chan *scannerv1.DiscoveredFile, len(f.files))
	go func() {
		defer close(ch)
		for _, fl := range f.files {
			select {
			case ch <- fl:
			case <-ctx.Done():
				return
			}
		}
	}()
	return ch, nil
}

func (f fakeScanner) Identify(context.Context, *scannerv1.IdentifyRequest) (*scannerv1.IdentifyResult, error) {
	return f.result, nil
}

